    if (it.kind === 'open') { var ch = (payload && payload.checked) || [], n = it.criteria.length, k = ch.filter(Boolean).length; var sc = n ? k / n : 0; return { ok: sc >= 0.6, score: sc }; }
    if (it.kind === 'prono') { var st = (payload && payload.stars) || [], m = st.length ? st.reduce(function (a, b) { return a + b; }, 0) / (3 * it.refs.length) : 0; return { ok: m >= 0.55, score: Math.min(1, m) }; }
